toolCall.argumentsJson:
{"CommandLine":"# Kill any hermes or python processes that might be locking the venv
Write-Host "Stopping any running Hermes processes..."
Get-Process | Where-Object { $_.Name -match "hermes|python|pythonw" } | ForEach-Object {
    Write-Host "  Stopping: $($_.Name) (PID $($_.Id))"
    Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
}
Write-Host "Done."

# Verify the locked file is now accessible
$lockedFile = "$env:LOCALAPPDATA\hermes\hermes-agent\venv\Lib\site-packages\aiohttp\_websocket\mask.cp312-win_amd64.pyd"
if (Test-Path $lockedFile) {
    Write-Host "Attempting to remove locked file..."
    Remove-Item $lockedFile -Force -ErrorAction SilentlyContinue
    if (Test-Path $lockedFile) {
        Write-Host "File still locked. Trying to remove entire venv..."
        Remove-Item "$env:LOCALAPPDATA\hermes\hermes-agent\venv" -Recurse -Force -ErrorAction SilentlyContinue
    }
}
Write-Host "Cleanup complete."","Cwd":"d:\Dev\hermes","WaitMsBeforeAsync":15000,"toolAction":"Killing locked processes","toolSummary":"Freeing venv file lock"}
